const stories=[{id:"st_akershus_slott_hvilket_akershus_skulle_bevares",quality_profile:"episode_v1",type:"conflict",title:"Hvilket Akershus skulle bevares?",year:1905,place_id:placeId,summary:"Restaureringen ble en strid om slottet skulle renses tilbake til én periode eller vise flere historiske lag.",story:"Da Holger Sinding-Larsen begynte de systematiske arbeidene i 1905, var oppgaven større enn å reparere mur. Hver åpnet vegg kunne vise middelalderborg, renessanseslott eller senere bruk, og hvert valg kunne samtidig fjerne et annet lag.\n\nTidlige planer ønsket å gjøre middelalderborgen tydeligere. Bevaringsdebatten endret retning da blant andre Harry Fett argumenterte for at flere perioder hadde historisk verdi. Restaurering ble dermed ikke en nøytral tilbakeføring, men et valg om hvilke Akershus som skulle være synlige.\n\nArnstein Arnebergs planer fra slutten av 1920-årene og det videre arbeidet fram mot 1962 formet salene som både historiske rom og moderne representasjonslokaler. Dagens slott er derfor et historisk dokument i to betydninger: gammelt materiale står igjen, og 1900-tallets vurderinger er bygget inn i det vi ser.",episode:{actors:["Holger Sinding-Larsen","Harry Fett","Arnstein Arneberg","antikvariske myndigheter"],date:"1905",action:"Systematiske undersøkelser og restaureringsarbeider begynte, samtidig som fagmiljøet diskuterte hvilke tidslag som skulle bevares.",consequence:"Flere historiske perioder ble bevart, og slottet ble gradvis innredet for ny representasjonsbruk."},sources:[{title:"SNL – Akershus slott og festning",url:urls.snl},{title:"Riksantikvaren – salene i nytt lys",url:urls.halls}],tags:["restaurering","kulturminnevern","autentisitet","representasjon"],related_people:["holger_sinding_larsen","arnstein_arneberg"],related_places:["akershus_festning"],next_scenes:[{place_id:"akershus_festning",reason:"Sammenlign slottsrestaureringen med hele festningsområdets bevaringshistorie."}],score:{narrative:5,historical:4,source:4,play_value:3,originality:3,total:19},arc:{start:"Restauratørene åpner et slott med mange historiske lag.",middle:"Fagmiljøet strides om én idealperiode eller flere tidslag.",end:"Flere lag blir del av et restaurert representasjonsslott."}}];const storyFile="data/stories/stories_akershus_slott.json";write(storyFile,stories);const sm=read("data/stories/stories_manifest.json");sm.files=sm.files.filter(x=>x.entity_id!==placeId);sm.files.push({category:"historie",entity_id:placeId,path:storyFile});write("data/stories/stories_manifest.json",sm);const em=read("data/stories/stories_episode_v1_manifest.json");addOnce(em.files,storyFile);write("data/stories/stories_episode_v1_manifest.json",em);

